// Chatwoot posts the event either at the top level or under body.
const root = $input.first().json;
const body = root.body || root;

// Only act on a newly created, incoming customer message.
if (body.event !== 'message_created') return [];
if (body.message_type !== 'incoming') return [];

const conv = body.conversation || {};
const meta = conv.meta || {};

// Human takeover gate. If a human agent is assigned, do nothing.
// This is the auto/manual toggle and must run before any OpenAI spend.
if (meta.assignee && meta.assignee.id) return [];

const sender = body.sender || meta.sender || {};
const phone = String(sender.phone_number || sender.identifier || '').replace(/[^0-9]/g, '');
if (!phone) return [];

const content = body.content || '';
const normalized = content.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

// Referral data (ctwa_clid, source_id) only arrives on the first message.
// Chatwoot may expose it under a few different keys, so check them all.
const add = conv.additional_attributes || {};
const catt = body.content_attributes || {};
const ref = add.referral || catt.referral || {};
const ctwa = String(add.ctwa_clid || ref.ctwa_clid || catt.ctwa_clid || '').replace(/[^A-Za-z0-9_-]/g, '');
const sourceId = String(add.source_id || ref.source_id || '').replace(/[^A-Za-z0-9_-]/g, '');

const convId = conv.id || null;
const contactId = sender.id || (meta.sender && meta.sender.id) || null;

// Opt-out detection. Only ever flips opted_out to true, never back.
const optOut = /\b(stop|unsubscribe|opt out|opt-out|remove me|do not message|dont message)\b/.test(normalized);

return [{ json: {
  conversation_id: convId,
  contact_sql: contactId === null ? 'NULL' : contactId,
  wa_id: phone,
  content,
  normalized,
  ctwa_clid: ctwa,
  ad_source_id: sourceId,
  opt_out: optOut ? 'true' : 'false'
} }];

const csv = $json.data || $json.body || '';
const serviceKey = $('Upsert Lead').first().json.service_key || '';

function parseCsv(text) {
  const rows = []; let cur = []; let val = ''; let q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) {
      if (c === '"') { if (text[i + 1] === '"') { val += '"'; i++; } else q = false; }
      else val += c;
    } else {
      if (c === '"') q = true;
      else if (c === ',') { cur.push(val); val = ''; }
      else if (c === '\n') { cur.push(val); rows.push(cur); cur = []; val = ''; }
      else if (c === '\r') { /* skip */ }
      else val += c;
    }
  }
  if (val.length || cur.length) { cur.push(val); rows.push(cur); }
  return rows;
}

const rows = parseCsv(csv).filter(r => r.length > 1);
if (rows.length < 2) return [{ json: { kb: '' } }];

const header = rows[0].map(h => h.trim().toLowerCase());
const idx = (n) => header.indexOf(n);
const out = [];
for (let i = 1; i < rows.length; i++) {
  const r = rows[i];
  const get = (n) => { const k = idx(n); return k >= 0 ? String(r[k] || '').trim() : ''; };
  const sk = get('service_key');
  if (sk && serviceKey && sk !== serviceKey && sk !== 'general') continue;
  const parts = [];
  if (get('service_name')) parts.push('Service: ' + get('service_name'));
  if (get('price_text')) parts.push('Price: ' + get('price_text'));
  if (get('turnaround')) parts.push('Turnaround: ' + get('turnaround'));
  if (get('description')) parts.push('Details: ' + get('description'));
  if (get('faq_question')) parts.push('Q: ' + get('faq_question') + ' A: ' + get('faq_answer'));
  if (parts.length) out.push(parts.join('. '));
}
return [{ json: { kb: out.join('\n') } }];

const tpl = $('Extract Prompt').first().json.data || '';
const kb = $('Parse Knowledge Base').first().json.kb || '';
const userText = $('Gate').first().json.content || '';

const system = tpl
  .replace(/{{\s*BUSINESS_NAME\s*}}/g, $env.BUSINESS_NAME || 'our studio')
  .replace(/{{\s*SERVICES\s*}}/g, $env.SERVICES || 'design services')
  .replace(/{{\s*LANGUAGES\s*}}/g, $env.LANGUAGES || 'English')
  .replace(/{{\s*KNOWLEDGE_BASE\s*}}/g, kb || 'No specific information supplied.');

return [{ json: {
  openaiBody: {
    model: $env.OPENAI_MODEL || 'gpt-4o-mini',
    temperature: 0.3,
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: userText }
    ]
  }
} }];

const c = $json.choices && $json.choices[0] && $json.choices[0].message ? $json.choices[0].message.content : '';
const reply = (c || 'Thanks for your message, a team member will follow up shortly.').trim();
return [{ json: { reply } }];

