const userText = ($('Gate').first().json.content || '').toLowerCase();
const reply = ($('Format Reply').first().json.reply || '').toLowerCase();
const kw = ['sample', 'samples', 'example', 'examples', 'portfolio', 'work', 'see your', 'show me', 'designs', 'reference'];
const relevant = kw.some(k => userText.includes(k) || reply.includes(k));
const serviceKey = $('Upsert Lead').first().json.service_key || 'general';
return [{ json: { relevant, serviceKey, waId: $('Gate').first().json.wa_id } }];

const type = $json.media_type === 'document' ? 'document' : 'image';
const body = { messaging_product: 'whatsapp', to: $('Decide Samples').first().json.waId, type };
body[type] = { id: $json.meta_media_id };
return { json: { mediaBody: body } };
